/* Scenario checker — dropdown lookup only, no verdict logic.
 *
 * THE ONE RULE
 * ------------
 * This file contains no verdict logic. It reads pre-computed answers from
 * window.MOE_CHECKER (generated by the Python build) and renders them.
 * If someone edits this file to change a verdict, the tests fail.
 */
(function () {
  'use strict';

  var D = window.MOE_CHECKER;
  if (!D || !D.a) return;

  function init() {
    var levelEl = document.getElementById('chk-level');
    var audEl = document.getElementById('chk-audience');
    var toolEl = document.getElementById('chk-tool');
    var btn = document.getElementById('chk-btn');
    var resultEl = document.getElementById('checker-result');

    if (!levelEl || !audEl || !toolEl || !btn || !resultEl) return;

    btn.addEventListener('click', function () {
      var key = levelEl.value + '|' + audEl.value + '|' + toolEl.value;
      var a = D.a[key];
      if (!a) {
        resultEl.innerHTML = '<p>We cannot answer that combination.</p>';
        resultEl.classList.add('visible');
        return;
      }
      render(a);
      trackEvent('checker_use', { verdict: a.v, tool: toolEl.value });
    });

    // Also check on any dropdown change
    [levelEl, audEl, toolEl].forEach(function (el) {
      el.addEventListener('change', function () {
        if (levelEl.value && audEl.value && toolEl.value) {
          btn.click();
        }
      });
    });
  }

  function render(a) {
    var resultEl = document.getElementById('checker-result');
    if (!resultEl) return;

    var verdictClass = 'v-' + a.v.toLowerCase();
    var verdictLabel = {
      'ALLOWED': 'Allowed',
      'SUPERVISED': 'Supervised',
      'NOT_ALLOWED': 'Not Allowed',
      'MUST_CHECK': 'Check Required',
      'UNKNOWN': 'Unknown'
    }[a.v] || a.v;

    var html = '<div class="result-header">';
    html += '<span class="result-verdict ' + verdictClass + '">' + verdictLabel + '</span>';
    html += '<span class="result-heading">' + esc(a.h) + '</span>';
    html += '</div>';

    // Reasons
    if (a.r && a.r.length) {
      html += '<div class="result-section"><h4>Why</h4><ul>';
      a.r.forEach(function (r) { html += '<li>' + esc(r) + '</li>'; });
      html += '</ul></div>';
    }

    // Conditions
    if (a.c && a.c.length) {
      html += '<div class="result-section"><h4>What you must do</h4><ul>';
      a.c.forEach(function (c) { html += '<li>' + esc(c) + '</li>'; });
      html += '</ul></div>';
    }

    // Escalation
    if (a.esc) {
      html += '<div class="result-escalate">' + esc(a.esc) + '</div>';
    }

    // Citations
    if (a.s && a.s.length) {
      html += '<div class="result-citations"><h4>MOE Sources</h4>';
      a.s.forEach(function (cite) {
        var publisher = esc(cite[0]);
        var url = esc(cite[1]);
        var quote = esc(cite[2]);
        html += '<div class="citation">';
        html += '<blockquote>"' + quote + '"</blockquote>';
        html += '<p class="cite-source">' + publisher + ' &mdash; <a href="' + url + '" target="_blank" rel="noopener">view source</a></p>';
        html += '</div>';
      });
      html += '</div>';
    }

    resultEl.innerHTML = html;
    resultEl.classList.add('visible');
  }

  function esc(s) {
    if (!s) return '';
    var d = document.createElement('div');
    d.appendChild(document.createTextNode(s));
    return d.innerHTML;
  }

  function trackEvent(name, props) {
    if (typeof plausible === 'function') {
      plausible(name, { props: props });
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
